insert into public.pfsa_records(kind,user_id,data) values
('task',null,'{"programme":"computer-cyber","week":1,"title":"Evidence intake and integrity","description":"Inventory every file in the supplied training ZIP; assign evidence IDs CC-01 onward and record size, SHA-256, source and collection time. Create separate originals and working folders. Hash before analysis and explain why copying an export is not a forensic disk acquisition. Write a chain-of-custody table with custodian, action, timestamp, purpose and integrity result. Hand-in: evidence_register.csv, sha256_manifest.csv, preservation_notes.pdf","due":"2026-11-23","url":"/guides/computer-cyber-task-guide.pdf#page=2","guide":"/guides/computer-cyber-task-guide.pdf","dataset":"/guides/computer-cyber-training-data.zip"}'::jsonb),
('task',null,'{"programme":"computer-cyber","week":2,"title":"File metadata examination","description":"Examine file_inventory.csv without editing the preserved copy. List each document version, supplied metadata and missing original-file properties. Compare report v1 and v2 metadata to the activity log. Identify conflicting or ambiguous records without assuming which source is correct. Build an observation table with evidence ID, exact row reference, observation, interpretation and confidence. Hand-in: metadata_comparison.csv and examination_notes.pdf","due":"2026-11-30","url":"/guides/computer-cyber-task-guide.pdf#page=3","guide":"/guides/computer-cyber-task-guide.pdf","dataset":"/guides/computer-cyber-training-data.zip"}'::jsonb),
('task',null,'{"programme":"computer-cyber","week":3,"title":"Correlated activity timeline","description":"Normalize all supplied timestamps to UTC and retain their original forms in a second column. Create a minimum eight-event timeline linking log records to inventory entries; flag events with no independent corroboration. Test two explanations for the report revision: expected editing and an unverified account action. List what evidence would distinguish them. Hand-in: timeline.csv, two_hypotheses.pdf and annotated references","due":"2026-12-07","url":"/guides/computer-cyber-task-guide.pdf#page=4","guide":"/guides/computer-cyber-task-guide.pdf","dataset":"/guides/computer-cyber-training-data.zip"}'::jsonb),
('task',null,'{"programme":"computer-cyber","week":4,"title":"Case report and peer handover","description":"Produce a 4-6 page report answering whether the supplied export supports a revision, who or what is named in logs, and what cannot be concluded. Include scope, methods, tool versions, hash checks, evidence citations, alternative explanations and limitations. Add a one-page handover checklist another student can reproduce from the training ZIP. Hand-in: final_report.pdf, timeline.csv, hash_manifest.csv and handover.pdf","due":"2026-12-14","url":"/guides/computer-cyber-task-guide.pdf#page=5","guide":"/guides/computer-cyber-task-guide.pdf","dataset":"/guides/computer-cyber-training-data.zip"}'::jsonb),
('task',null,'{"programme":"mobile","week":1,"title":"Logical export preservation","description":"Inventory device.json, messages.csv and app_events.csv. Record device label, export type, timezone and fields absent from the export. Hash every supplied file; prepare an evidence register and a consent/scope statement for the fictional training device. Draw the difference between a logical export, a physical extraction and an original device; state which one is available here. Hand-in: device_profile.pdf, evidence_register.csv and hash_manifest.csv","due":"2026-11-23","url":"/guides/mobile-task-guide.pdf#page=2","guide":"/guides/mobile-task-guide.pdf","dataset":"/guides/mobile-training-data.zip"}'::jsonb),
('task',null,'{"programme":"mobile","week":2,"title":"Messages and app activity","description":"Map message ID, sender label, direction, timestamp and text into an examination worksheet; use synthetic labels only. Identify duplicate message IDs and explain the risk of counting duplicates as independent events. Compare app events with message activity. Mark correlation separately from proof of a person using the device. Hand-in: message_worksheet.csv, duplicate_log.csv and observations.pdf","due":"2026-11-30","url":"/guides/mobile-task-guide.pdf#page=3","guide":"/guides/mobile-task-guide.pdf","dataset":"/guides/mobile-training-data.zip"}'::jsonb),
('task',null,'{"programme":"mobile","week":3,"title":"Timezone and event correlation","description":"Convert the +05:30 timestamps to UTC and preserve both representations. Construct a timeline of at least eight distinct events, explicitly retaining any duplicates or uncertain ordering in notes. Evaluate whether app activity corroborates a message event; explain why a logical export cannot establish deleted content or complete device history. Hand-in: mobile_timeline.csv and correlation_matrix.pdf","due":"2026-12-07","url":"/guides/mobile-task-guide.pdf#page=4","guide":"/guides/mobile-task-guide.pdf","dataset":"/guides/mobile-training-data.zip"}'::jsonb),
('task',null,'{"programme":"mobile","week":4,"title":"Mobile evidence report","description":"Write a 4-6 page report including fictional scope, export limitations, findings and evidence-row citations. Redact synthetic message text from the executive summary unless relevant; describe how real participant data would be minimized. Package the timeline, hashes, duplicate decisions and a reproducible handover checklist. Hand-in: mobile_report.pdf, timeline.csv and appendix.zip","due":"2026-12-14","url":"/guides/mobile-task-guide.pdf#page=5","guide":"/guides/mobile-task-guide.pdf","dataset":"/guides/mobile-training-data.zip"}'::jsonb),
('task',null,'{"programme":"network","week":1,"title":"Network evidence inventory","description":"Inventory flows.csv and dns.csv, hash both and document collection assumptions. Draw a topology using the two client addresses and named resolver; distinguish source/destination fields from device ownership. Create a field dictionary including timestamp timezone, ports, byte counts and direction. State that packet payloads are not included. Hand-in: network_map.pdf, field_dictionary.csv and evidence_register.csv","due":"2026-11-23","url":"/guides/network-task-guide.pdf#page=2","guide":"/guides/network-task-guide.pdf","dataset":"/guides/network-training-data.zip"}'::jsonb),
('task',null,'{"programme":"network","week":2,"title":"Baseline and outlier description","description":"Group the supplied flows by source, destination and service; calculate event count and bytes for each group. Describe the largest transfer relative to the rest of this small dataset; do not call it exfiltration based solely on size. Match DNS responses to flows within a documented time window, marking multiple possible matches and missing queries. Hand-in: flow_summary.csv, dns_mapping.csv and interpretation_notes.pdf","due":"2026-11-30","url":"/guides/network-task-guide.pdf#page=3","guide":"/guides/network-task-guide.pdf","dataset":"/guides/network-training-data.zip"}'::jsonb),
('task',null,'{"programme":"network","week":3,"title":"Flow and DNS timeline","description":"Merge DNS and flow events into a UTC timeline with original record IDs. Select one unusual sequence and compare a routine backup explanation with an unverified transfer explanation. List the packet, endpoint and application evidence needed to resolve uncertainty; identify what metadata alone cannot reveal. Hand-in: network_timeline.csv, hypothesis_matrix.pdf and evidence_gaps.pdf","due":"2026-12-07","url":"/guides/network-task-guide.pdf#page=4","guide":"/guides/network-task-guide.pdf","dataset":"/guides/network-training-data.zip"}'::jsonb),
('task',null,'{"programme":"network","week":4,"title":"Network investigation report","description":"Prepare a 4-6 page report with a topology, aggregate tables, one chart and the selected event sequence. Cite row IDs for every finding and distinguish measured values from assumptions. Provide reproducible grouping/filter criteria and integrity checks so a reviewer can rebuild the results. Hand-in: network_report.pdf, analysis_tables.csv and reproducibility_notes.pdf","due":"2026-12-14","url":"/guides/network-task-guide.pdf#page=5","guide":"/guides/network-task-guide.pdf","dataset":"/guides/network-training-data.zip"}'::jsonb),
('task',null,'{"programme":"cloud","week":1,"title":"Cloud audit scope and preservation","description":"Inventory audit.jsonl and assets.csv; hash files and record the fictional tenant boundary. Map event ID, principal, action, target, result and timestamp. Separate user principals from service accounts. Write a preservation plan covering retention, export method and missing provider-side context. Hand-in: cloud_scope.pdf, evidence_register.csv and field_map.csv","due":"2026-11-23","url":"/guides/cloud-task-guide.pdf#page=2","guide":"/guides/cloud-task-guide.pdf","dataset":"/guides/cloud-training-data.zip"}'::jsonb),
('task',null,'{"programme":"cloud","week":2,"title":"Identity and configuration review","description":"Classify supplied events into authentication, object access and configuration changes. Build a principal-action matrix and identify denied actions separately from successful access. Review the configuration-change event and list what before/after state evidence would be required to judge its effect. Hand-in: principal_matrix.csv, access_review.csv and configuration_notes.pdf","due":"2026-11-30","url":"/guides/cloud-task-guide.pdf#page=3","guide":"/guides/cloud-task-guide.pdf","dataset":"/guides/cloud-training-data.zip"}'::jsonb),
('task',null,'{"programme":"cloud","week":3,"title":"Object-access timeline","description":"Correlate authentication, object reads and configuration events using event IDs and UTC time. Compare a scheduled automation explanation with an unverified account-use explanation for the service activity. Document gaps caused by export scope, log delay, shared credentials or absent content records; do not infer file contents from a read event. Hand-in: cloud_timeline.csv and confidence_assessment.pdf","due":"2026-12-07","url":"/guides/cloud-task-guide.pdf#page=4","guide":"/guides/cloud-task-guide.pdf","dataset":"/guides/cloud-training-data.zip"}'::jsonb),
('task',null,'{"programme":"cloud","week":4,"title":"Cloud case report","description":"Write a 4-6 page provider-neutral report describing scope, identity context, chronology and observed changes. Cite the exact audit event IDs supporting each finding and note that these logs are fictional teaching data. Deliver a handover pack with hashes, field map, principal matrix, queries or filters, and unresolved questions. Hand-in: cloud_report.pdf and cloud_appendix.zip","due":"2026-12-14","url":"/guides/cloud-task-guide.pdf#page=5","guide":"/guides/cloud-task-guide.pdf","dataset":"/guides/cloud-training-data.zip"}'::jsonb),
('task',null,'{"programme":"database","week":1,"title":"Read-only database intake","description":"Inventory training.db and schema.sql, compute SHA-256 values and preserve originals. Open only a working copy in read-only mode. List tables, column meanings, primary keys and relationships. Record engine/tool versions and explain the absence of transaction logs, original host context and a historical snapshot. Hand-in: schema_map.pdf, evidence_register.csv and read_only_method.pdf","due":"2026-11-23","url":"/guides/database-task-guide.pdf#page=2","guide":"/guides/database-task-guide.pdf","dataset":"/guides/database-training-data.zip"}'::jsonb),
('task',null,'{"programme":"database","week":2,"title":"Integrity and consistency checks","description":"Count rows by table and check duplicate order IDs, null required fields and references to missing customers. Compare recorded order totals to quantities and unit prices, keeping the exact SELECT statements used. Distinguish intentionally unusual training records from conclusions about misconduct; explain limitations of the supplied schema. Hand-in: checks.sql, integrity_results.csv and discrepancy_notes.pdf","due":"2026-11-30","url":"/guides/database-task-guide.pdf#page=3","guide":"/guides/database-task-guide.pdf","dataset":"/guides/database-training-data.zip"}'::jsonb),
('task',null,'{"programme":"database","week":3,"title":"Audit trail reconstruction","description":"Join audit records to orders using their identifiers and sort changes by timestamp. Compare before_value, after_value and the final order amount. Flag a missing or inconsistent audit transition. Explain why an application-level audit record is not a complete database transaction log or proof of actor identity. Hand-in: audit_timeline.csv, reconstruction.sql and limitations.pdf","due":"2026-12-07","url":"/guides/database-task-guide.pdf#page=4","guide":"/guides/database-task-guide.pdf","dataset":"/guides/database-training-data.zip"}'::jsonb),
('task',null,'{"programme":"database","week":4,"title":"Database findings report","description":"Write a 4-6 page report with schema, read-only method, integrity checks and a reconstruction of two selected orders. Include query text, result excerpts, row IDs and the difference between observed inconsistency and attribution. Re-hash the preserved original and provide a reproducibility appendix for all SELECT queries. Hand-in: database_report.pdf, queries.sql and results.zip","due":"2026-12-14","url":"/guides/database-task-guide.pdf#page=5","guide":"/guides/database-task-guide.pdf","dataset":"/guides/database-training-data.zip"}'::jsonb),
('task',null,'{"programme":"iot","week":1,"title":"Device ecosystem mapping","description":"Inventory devices.csv, telemetry.csv and gateway.csv; compute file hashes and assign evidence IDs. Draw device-to-gateway relationships and list the device clock assumptions and measurement units. Describe an appropriate preservation plan for a real device, while stating no actual hardware acquisition occurs in this exercise. Hand-in: ecosystem_map.pdf, evidence_register.csv and preservation_plan.pdf","due":"2026-11-23","url":"/guides/iot-task-guide.pdf#page=2","guide":"/guides/iot-task-guide.pdf","dataset":"/guides/iot-training-data.zip"}'::jsonb),
('task',null,'{"programme":"iot","week":2,"title":"Telemetry quality review","description":"Group readings by device and compute count, minimum, maximum and time gaps. Identify duplicate sequence numbers, missing intervals and the deliberately offset sensor clock. Decide whether each anomaly may reflect collection loss, clock drift or a device event; keep observations and hypotheses separate. Hand-in: telemetry_summary.csv, quality_flags.csv and reasoning.pdf","due":"2026-11-30","url":"/guides/iot-task-guide.pdf#page=3","guide":"/guides/iot-task-guide.pdf","dataset":"/guides/iot-training-data.zip"}'::jsonb),
('task',null,'{"programme":"iot","week":3,"title":"Gateway and device correlation","description":"Normalize time using a clearly stated clock-offset assumption; preserve raw device timestamps. Correlate gateway reconnect events with telemetry gaps and flag matches that depend on an assumption. Create a chronology with confidence and evidence references. Explain why a reconnect is not automatically evidence of tampering. Hand-in: iot_timeline.csv, clock_assumptions.pdf and correlation_table.csv","due":"2026-12-07","url":"/guides/iot-task-guide.pdf#page=4","guide":"/guides/iot-task-guide.pdf","dataset":"/guides/iot-training-data.zip"}'::jsonb),
('task',null,'{"programme":"iot","week":4,"title":"IoT case report","description":"Prepare a 4-6 page report with ecosystem diagram, telemetry quality results and correlated gateway chronology. Explain the impact of clock differences, absent firmware history and unavailable physical-device context. Include hashes, transformation notes, anomaly definitions and an independent-review checklist. Hand-in: iot_report.pdf and iot_appendix.zip","due":"2026-12-14","url":"/guides/iot-task-guide.pdf#page=5","guide":"/guides/iot-task-guide.pdf","dataset":"/guides/iot-training-data.zip"}'::jsonb);
